#if os(Android)
    import CJNI
    import SheetMusicAudioSwiftySynthCore

    /// `SwiftySynthNative.nativeRender(handle, frames, left, right)`: renders `frames` stereo frames of the synth
    /// behind `handle` into the start of the two Kotlin arrays and answers `frames`, or 0 — arrays untouched — for an
    /// unknown handle, a non-positive count or arrays too short.
    ///
    /// Written by hand rather than generated by swift-java, whose `[Float]` bridging would copy each array into a new
    /// Swift array and back every block on the audio writer thread. This crosses JNI once per synth per block and
    /// allocates nothing: `GetPrimitiveArrayCritical` hands over the arrays' own storage.
    ///
    /// The synth's lock is taken *before* the arrays are pinned: nothing may block inside a critical region — the VM
    /// may hold its garbage collector off for it — so any wait for a control call holding the lock happens outside one.
    @_cdecl("Java_io_github_jiyimeta_sheetmusic_audio_synth_SwiftySynthNative_nativeRender")
    // swiftlint:disable:next identifier_name
    public func Java_io_github_jiyimeta_sheetmusic_audio_synth_SwiftySynthNative_nativeRender(
        _ envPointer: UnsafeMutablePointer<JNIEnv?>,
        _: jobject?,
        _ handle: jlong,
        _ frames: jint,
        _ left: jfloatArray?,
        _ right: jfloatArray?,
    ) -> jint {
        guard frames > 0, let env = envPointer.pointee, let left, let right,
              let synth = SynthBridge.synth(Int64(handle)),
              env.pointee.GetArrayLength(envPointer, left) >= frames,
              env.pointee.GetArrayLength(envPointer, right) >= frames
        else { return 0 }
        return synth.withLock {
            guard let leftStorage = env.pointee.GetPrimitiveArrayCritical(envPointer, left, nil) else { return 0 }
            guard let rightStorage = env.pointee.GetPrimitiveArrayCritical(envPointer, right, nil) else {
                env.pointee.ReleasePrimitiveArrayCritical(envPointer, left, leftStorage, JNI_ABORT)
                return 0
            }
            synth.renderHoldingLock(
                left: leftStorage.assumingMemoryBound(to: Float.self),
                right: rightStorage.assumingMemoryBound(to: Float.self),
                frames: Int(frames),
            )
            env.pointee.ReleasePrimitiveArrayCritical(envPointer, right, rightStorage, 0)
            env.pointee.ReleasePrimitiveArrayCritical(envPointer, left, leftStorage, 0)
            return frames
        }
    }
#endif
